template <typename Ch, typename Tr>
Tr::int_type do_input_op()
{
    // RAII Guard: checks state, flushes tied streams, sets locale
    sentry s(*this, true); // Optional flag: skipws

    if (s) {
        // Stream is valid and prepared for input
        // Actual reading operation (e.g., from rdbuf())
        return rdbuf()->sbumpc();
    }

    // Sentry failed initialization or state was bad
    setstate(failbit);
    return Tr::eof();
    // Sentry destructor restores state/performs cleanup
}
